"""Validation rules migrated from legacy/opportunity_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(image: dict | None, column: str) -> Any:
    if image is None:
        return ""
    value = image.get(column, "")
    return "" if value is None else value


def _text(value: Any) -> str:
    if value is None:
        return ""
    return str(value)


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_gte(left: Any, right: Any) -> bool:
    left_text = _text(left)
    right_text = _text(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate all applicable opportunity rules in legacy rule-file order."""
    errors: list[dict] = []

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {"code": code, "message": message, "severity": severity}
        )

    if event in ("INSERT", "UPDATE"):
        # OPP-001
        if not (_number(_nvl(_value(record, "AMT"), 0)) >= Decimal(0)):
            fail("E3001", "Amount negative")

        # OPP-002
        if (
            _text(_value(record, "STAT_CD")) == "W"
            and _number(_nvl(_value(record, "AMT"), 0)) == Decimal(0)
        ):
            fail("E3002", "Won opportunity requires amount")

        # OPP-003
        if (
            _text(_value(record, "STAT_CD")) == "L"
            and _text(_value(record, "LOST_RSN")) == ""
        ):
            fail("E3003", "Lost reason required")

        # OPP-004
        if (
            _text(_value(record, "STAT_CD")) == "W"
            and _text(_value(record, "CLOSE_DT")) == "00000000"
        ):
            fail("E3004", "Won opportunity requires close date")

    if event == "UPDATE":
        # OPP-005
        if (
            _text(_value(old, "STAT_CD")) == "W"
            and _text(_value(record, "STAT_CD")) != "W"
        ):
            fail("E3005", "Cannot reopen a won opportunity")

    if event in ("INSERT", "UPDATE"):
        # OPP-006
        status = _text(_value(record, "STAT_CD"))
        stage = _number(_value(record, "STAGE_PCT"))
        stage_is_consistent = (
            (status == "P" and stage == Decimal(10))
            or (status == "Q" and stage == Decimal(25))
            or (status == "N" and stage == Decimal(60))
            or (status == "W" and stage == Decimal(100))
            or (status == "L" and stage == Decimal(0))
        )
        if not stage_is_consistent:
            fail("E3006", "Stage percent inconsistent with status")

    if event == "INSERT":
        # OPP-007
        close_date = _text(_value(record, "CLOSE_DT"))
        if not (
            close_date == "00000000"
            or _date_gte(close_date, today)
        ):
            fail("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return True exactly when at least one collected failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
